import React from 'react';
import { motion } from 'framer-motion';
import { FileText, Upload, Settings, LogOut } from 'lucide-react';
import './Dashboard.css';

const Dashboard = () => {
  const handleLogout = () => {
    // In a real app, this would clear authentication tokens
    window.location.href = '/login';
  };

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <div className="header-content">
          <div className="logo">
            <FileText className="logo-icon" />
            <span className="logo-text">AI PDF Reader</span>
          </div>
          <button className="logout-button" onClick={handleLogout}>
            <LogOut size={20} />
            Logout
          </button>
        </div>
      </header>

      <main className="dashboard-main">
        <motion.div
          className="welcome-section"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
        >
          <h1>Welcome to AI PDF Reader</h1>
          <p>Upload and analyze your PDF documents with AI assistance</p>
        </motion.div>

        <div className="dashboard-grid">
          <motion.div
            className="dashboard-card"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            <Upload className="card-icon" />
            <h3>Upload PDF</h3>
            <p>Upload your PDF documents for AI analysis</p>
          </motion.div>

          <motion.div
            className="dashboard-card"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            <FileText className="card-icon" />
            <h3>Recent Files</h3>
            <p>Access your recently analyzed documents</p>
          </motion.div>

          <motion.div
            className="dashboard-card"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            <Settings className="card-icon" />
            <h3>Settings</h3>
            <p>Configure your AI PDF Reader preferences</p>
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default Dashboard;
